referenceSolutions.javascript:
export function employeeFreeTime(schedules              )             {
const a=schedules.flat().map(x=>[...x]).sort((x,y)=>x[0]-y[0]);if(!a.length)return [];let end=a[0][1];const out           =[];for(let i=1;i<a.length;i++){if(a[i][0]>end)out.push([end,a[i][0]]);end=Math.max(end,a[i][1]);}return out;
}

